// Parsear el payload de Fathom
// Ajustar rutas según el payload real (verificar con primer webhook)
const body = $input.first().json;
const data = body.data || body;

const call_id = data.id || '';
const titulo = data.title || 'Llamada sin título';
const fecha = data.date || new Date().toISOString();
const duracion_seg = data.duration || 0;
const duracion_min = Math.round(duracion_seg / 60);
const transcripcion = data.transcript || '';

const attendees = data.attendees || [];
const vendedor = attendees[0]?.name || '';
const cliente = attendees[1]?.name || '';

return [{
  json: { call_id, titulo, fecha, duracion_min, transcripcion, vendedor, cliente }
}];

// Parsear la respuesta de Groq
const groqResponse = $input.first().json;
const content = groqResponse.choices?.[0]?.message?.content || '{}';

let analysis = { objeciones: [], definiciones: [] };
try {
  analysis = JSON.parse(content);
} catch(e) {
  // Si no parsea, devolver arrays vacíos
  console.log('Error parseando Groq:', e.message);
}

const objeciones = Array.isArray(analysis.objeciones) ? analysis.objeciones : [];
const definiciones = Array.isArray(analysis.definiciones) ? analysis.definiciones : [];

return [{
  json: {
    objeciones,
    definiciones,
    objeciones_json: JSON.stringify(objeciones),
    definiciones_json: JSON.stringify(definiciones),
    notion_page_id: $('Notion — Crear Llamada').first().json.id,
    call_id: $('Parse Fathom Payload').first().json.call_id,
    titulo: $('Parse Fathom Payload').first().json.titulo,
    fecha: $('Parse Fathom Payload').first().json.fecha,
    cliente: $('Parse Fathom Payload').first().json.cliente,
    transcripcion: $('Parse Fathom Payload').first().json.transcripcion
  }
}];
